// BEGIN src/js/norm.js
// Text normalisation and ticket keys (ARCHITECTURE C-4, section 8; ADR-006). H1 Intake Guard.
// JS twin of src/common/norm.py: same whitespace class, same preimages. toLowerCase stands in for Python
// casefold (OPEN_QUESTIONS Q-19). Plain ES2019, no require, so the file pastes into an n8n Code node.
// tests/test_workflow.py runs it under node on the tests/test_norm.py vectors and compares with Python.
// Entry points: textNorm, emailNorm, sha256Hex, dedupeKey, contentSha256.

// Same class as src/common/norm.py WHITESPACE.
var NORM_WHITESPACE = /[\t\n\x0b\x0c\r\x1c-\x20\x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+/g;
var DEDUPE_KEY_HEX = 20;

function textNorm(value) {
  if (value === null || value === undefined) return '';
  var text = String(value).normalize('NFKC').toLowerCase();
  return text.replace(NORM_WHITESPACE, ' ').replace(/^ +| +$/g, '');
}

function emailNorm(value) {
  return textNorm(value).split(' ').join('');
}

function utf8Bytes(text) {
  var out = [];
  for (var i = 0; i < text.length; i++) {
    var c = text.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < text.length) {
      var low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        c = 0x10000 + ((c - 0xd800) << 10) + (low - 0xdc00);
        i++;
      }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

var SHA256_K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];

function rotr(x, n) { return (x >>> n) | (x << (32 - n)); }

// Dependency-free SHA-256 of the UTF-8 bytes of `text` (ported from T2 H1 PDF SHA-256), lower-case hex.
function sha256Hex(text) {
  var bytes = utf8Bytes(String(text));
  var len = bytes.length;
  var total = Math.ceil((len + 9) / 64) * 64;
  var msg = new Uint8Array(total);
  msg.set(bytes);
  msg[len] = 0x80;
  var view = new DataView(msg.buffer);
  view.setUint32(total - 8, Math.floor(len * 8 / 0x100000000));
  view.setUint32(total - 4, (len * 8) >>> 0);
  var H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  var W = new Uint32Array(64);
  for (var off = 0; off < total; off += 64) {
    var t;
    for (t = 0; t < 16; t++) W[t] = view.getUint32(off + t * 4);
    for (t = 16; t < 64; t++) {
      var s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      var s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    var a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (t = 0; t < 64; t++) {
      var t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + SHA256_K[t] + W[t]) >>> 0;
      var t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map(function (x) { return ('00000000' + x.toString(16)).slice(-8); }).join('');
}

// First 20 hex of sha256(source + "|" + message_id) over the raw values. Empty or missing -> null
// (Python raises ValueError; intake rejects the ticket, C-3).
function dedupeKey(source, messageId) {
  if (!source || !messageId) return null;
  return sha256Hex(String(source) + '|' + String(messageId)).slice(0, DEDUPE_KEY_HEX);
}

function contentSha256(fromEmail, subject, body) {
  return sha256Hex(emailNorm(fromEmail) + '|' + textNorm(subject) + '|' + textNorm(body));
}
// END src/js/norm.js

// C-2 size and type limits, C-3 required fields, C-4 keys on raw input. Raw text leaves intake only via H3.
const item = $input.first().json;
const WEBHOOK_KEYS = ['headers', 'params', 'query', 'body', 'webhookUrl', 'executionMode'];
const cfg = {};
Object.keys(item).forEach((key) => { if (WEBHOOK_KEYS.indexOf(key) < 0) cfg[key] = item[key]; });
const headers = item.headers || {};
const t = (item.body && typeof item.body === 'object' && !Array.isArray(item.body)) ? item.body : {};
const runId = String(headers['x-replay-run-id'] || ('day-' + new Date().toISOString().slice(0, 10)));
const inputRef = String(headers['x-replay-input-id'] || '');
const subject = typeof t.subject === 'string' ? t.subject : '';
const body = typeof t.body_text === 'string' ? t.body_text : '';
const attachments = Array.isArray(t.attachments) ? t.attachments : [];
const allowed = Array.isArray(cfg.allowed_attachment_types) ? cfg.allowed_attachment_types
  : JSON.parse(String(cfg.allowed_attachment_types || '[]'));
let code = '';
if (!t.source || !t.from_email) code = 'missing_field';
else if (!t.source_message_id) code = 'missing_message_id';
else if (!subject.trim() && !body.trim()) code = 'empty_content';
else if (body.length > Number(cfg.max_body_chars)) code = 'body_too_long';
else if (subject.length > Number(cfg.max_subject_chars)) code = 'subject_too_long';
else if (attachments.length > Number(cfg.max_attachments)) code = 'too_many_attachments';
else if (attachments.some((a) => !a || allowed.indexOf(String(a.type || '')) < 0)) code = 'attachment_type';
const keys = {
  dedupe_key: dedupeKey(t.source, t.source_message_id) || '',
  content_sha256: contentSha256(t.from_email, subject, body),
};
const base = { ...cfg, run_id: runId, input_ref: inputRef, started_ms: Date.now(), ...keys };
if (code) {
  return [{ json: { ...base, error_stage: 'intake', error_node: 'H1 Intake Guard', error_code: 'reject:' + code,
    error_message: 'intake limit or required field: ' + code } }];
}
// Attachment metadata only (name, type, bytes); no binary is read.
return [{ json: { ...base, ticket: { from_name: String(t.from_name || ''), subject, body_text: body,
  attachments: attachments.map((a) => ({ name: String(a.name || ''), type: String(a.type || ''),
    bytes: Number(a.bytes || 0) })) } } }];

// C-18 steps 1-2, before any model spend: a jira_links row with this dedupe_key, or a routed or queued audit row
// with this content_sha256, makes the ticket a duplicate_skip.
const item = $('H1 Intake Guard').first(0).json;
const links = ($('H2 Link Lookup').first(0).json || {}).rows || [];
const same = ($json || {}).rows || [];
const via = links.length ? 'jira_links' : (same.length ? 'content' : '');
const issueKey = String((links.length ? links[0].issue_key : (same.length ? same[0].issue_key : '')) || '');
return [{ json: { ...item, dedupe_route: via ? 'duplicate' : 'new', duplicate_via: via,
  duplicate_issue_key: issueKey } }];

// BEGIN src/js/redact.js
// PII redaction before the model and before any write (ARCHITECTURE C-5, ADR-004). H3 Redact.
// JS twin of src/common/redact.py: same patterns, same order, same placeholders. Plain ES2019, no require,
// so the file pastes into an n8n Code node. tests/test_redact.py runs it under node on the shared vectors.
// Entry point: redactTicket(ticket) -> {redacted_subject, redacted_body, pii_counts}.

var PII_TYPES = ['email', 'phone', 'card', 'iban', 'ssn', 'ipv4', 'url', 'name'];

var REDACT_OCTET = '(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])';
var REDACT_PATTERNS = {
  url: '[Hh][Tt][Tt][Pp][Ss]?://[^ \\t\\r\\n<>"\'|()\\[\\]{}]+\\?[^ \\t\\r\\n<>"\'|()\\[\\]{}]+',
  email: '[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}',
  iban: '(?<![A-Za-z0-9])[A-Z]{2}[0-9]{2}(?: ?[A-Z0-9]{4}){2,7}(?: ?[A-Z0-9]{1,3})?(?![A-Za-z0-9])',
  card: '(?<![0-9])[0-9](?:[ -]?[0-9]){12,18}(?![0-9])',
  ssn: '(?<![0-9])[0-9]{3}-[0-9]{2}-[0-9]{4}(?![0-9])',
  ipv4: '(?<![0-9.])(?:' + REDACT_OCTET + '\\.){3}' + REDACT_OCTET + '(?![0-9]|\\.[0-9])',
  phone: '(?<![A-Za-z0-9+])(?:(?:\\+1[ .-]?)?(?:\\([0-9]{3}\\)[ .-]?|[0-9]{3}[ .-])[0-9]{3}[ .-][0-9]{4}' +
         '|\\+[0-9]{1,3}(?:[ .-]?(?:\\([0-9]{1,4}\\)|[0-9]{1,4})){2,5})(?![A-Za-z0-9])'
};
var REDACT_ORDER = ['url', 'email', 'iban', 'card', 'ssn', 'ipv4', 'phone'];

function isDigit(c) { return c >= '0' && c <= '9'; }

function luhnOk(text) {
  var digits = [];
  for (var k = 0; k < text.length; k++) { if (isDigit(text[k])) digits.push(+text[k]); }
  if (digits.length < 13 || digits.length > 19) return false;
  var total = 0;
  for (var i = 0; i < digits.length; i++) {
    var d = digits[digits.length - 1 - i];
    if (i % 2) { d *= 2; if (d > 9) d -= 9; }
    total += d;
  }
  return total % 10 === 0;
}

function ibanOk(text) {
  var code = text.split(' ').join('');
  if (code.length < 15 || code.length > 34) return false;
  var moved = code.slice(4) + code.slice(0, 4);
  var rem = 0;
  for (var i = 0; i < moved.length; i++) {
    var c = moved[i];
    var value = isDigit(c) ? c : String(c.charCodeAt(0) - 55);
    for (var j = 0; j < value.length; j++) rem = (rem * 10 + (+value[j])) % 97;
  }
  return rem === 1;
}

function phoneOk(text) {
  var n = 0;
  for (var i = 0; i < text.length; i++) { if (isDigit(text[i])) n++; }
  return n >= 7 && n <= 15;
}

var REDACT_CHECKS = { iban: ibanOk, card: luhnOk, phone: phoneOk };

function newRedactState() {
  var state = { counts: {}, seen: {} };
  for (var i = 0; i < PII_TYPES.length; i++) { state.counts[PII_TYPES[i]] = 0; state.seen[PII_TYPES[i]] = {}; }
  return state;
}

function redactPlaceholder(state, kind, value) {
  var seen = state.seen[kind];
  if (!Object.prototype.hasOwnProperty.call(seen, value)) seen[value] = Object.keys(seen).length + 1;
  state.counts[kind] += 1;
  return '[' + kind.toUpperCase() + '_' + seen[value] + ']';
}

function isWordChar(ch) {
  return /[A-Za-z0-9_]/.test(ch) || ch.charCodeAt(0) >= 128;
}

function namePartsOf(displayName) {
  if (!displayName) return [];
  var full = String(displayName).split('"').join(' ').split(' ').filter(function (p) { return p; }).join(' ');
  if (!full) return [];
  var uniq = [];
  full.split(' ').forEach(function (p) { if (uniq.indexOf(p) < 0) uniq.push(p); });
  uniq.sort(function (a, b) {
    if (a.length !== b.length) return b.length - a.length;
    return a < b ? -1 : (a > b ? 1 : 0);
  });
  var parts = [full];
  uniq.forEach(function (p) { if (p.length >= 2 && parts.indexOf(p) < 0) parts.push(p); });
  return parts;
}

function redactName(text, displayName, state) {
  namePartsOf(displayName).forEach(function (part) {
    var out = [];
    var i = 0;
    for (;;) {
      var j = text.indexOf(part, i);
      if (j < 0) break;
      var end = j + part.length;
      if ((j > 0 && isWordChar(text[j - 1])) || (end < text.length && isWordChar(text[end]))) {
        out.push(text.slice(i, j + 1));
        i = j + 1;
        continue;
      }
      out.push(text.slice(i, j));
      // Every form of the sender's name is one person: one placeholder.
      out.push(redactPlaceholder(state, 'name', 'sender'));
      i = end;
    }
    out.push(text.slice(i));
    text = out.join('');
  });
  return text;
}

function redactText(text, displayName, state) {
  if (!state) state = newRedactState();
  if (text === null || text === undefined) return '';
  text = String(text);
  REDACT_ORDER.forEach(function (kind) {
    var flags = 'g';
    var check = REDACT_CHECKS[kind];
    text = text.replace(new RegExp(REDACT_PATTERNS[kind], flags), function (m) {
      if (check && !check(m)) return m;
      return redactPlaceholder(state, kind, m);
    });
  });
  return redactName(text, displayName, state);
}

function redactTicket(ticket) {
  var state = newRedactState();
  var name = ticket.from_name;
  var subject = redactText(ticket.subject, name, state);
  var body = redactText(ticket.body_text, name, state);
  var counts = {};
  PII_TYPES.forEach(function (t) { counts[t] = state.counts[t]; });
  return { redacted_subject: subject, redacted_body: body, pii_counts: counts };
}
// END src/js/redact.js

// C-5: redact before the model and before any write; the raw ticket is dropped from the item here.
const item = $input.first().json;
const ticket = item.ticket || {};
const red = redactTicket(ticket);
const nameState = newRedactState();
const names = (ticket.attachments || []).map((a) => redactText(a.name, ticket.from_name, nameState));
const out = { ...item, ...red, attachment_names: names };
delete out.ticket;
return [{ json: out }];

// BEGIN src/js/inject.js
// Injection scan and model text cap on redacted text (ARCHITECTURE C-6, C-7). H4 Injection Scan + Cap.
// JS twin of src/common/inject.py: same patterns, same scan text, same model text. Plain ES2019, no require,
// so the file pastes into an n8n Code node. tests/test_inject.py runs it under node on the shared vectors.
// Entry point: scanAndCap(redacted, attachmentNames, maxModelChars) -> {model_text, injection_signals, truncated}.

var MAX_MODEL_CHARS = 6000;

var INJECT_PHRASES = [
  ['instruction_override',
    '\\b(?:ignore|disregard|forget|override|bypass)(?: (?:all|any|of|the|your|my|these|those|previous|prior|above' +
    '|earlier|preceding|existing|original|system|other))* (?:instructions?|rules|prompts?|directions|guidelines' +
    '|directives)\\b'],
  ['role_override',
    '\\byou are now (?:an? |the |in )?(?:[a-z]+ ){0,2}(?:assistant|ai|admin|administrator|system|bot|model|agent' +
    '|mode)\\b|\\b(?:act|behave) as (?:an? |the )?(?:admin|administrator|system|developer|root|unrestricted' +
    '|jailbroken)\\b|\\bdeveloper mode\\b|\\bjailbreak|\\bdo anything now\\b'],
  ['prompt_extraction',
    '\\b(?:reveal|show|print|repeat|output|display|tell me|give me|share|leak|dump)(?: me| us)? (?:(?:your|the|its) )?' +
    '(?:(?:full|hidden|initial|original|internal|secret) )?(?:system prompt|system message|developer message' +
    '|instructions you (?:use|follow|were given))\\b'],
  ['data_exfil',
    '\\b(?:repeat|include|copy|paste|print|output|reveal|leak|echo|expose)(?: (?:the|this|my|our|their|all|full' +
    '|every))?(?: (?:customer\'s|user\'s|client\'s|customer|user|client))? (?:full )?(?:card numbers?' +
    '|credit card(?: numbers?)?|card details|ssns?|social security numbers?|ibans?|passwords?|api keys?' +
    '|access tokens?|credentials|secrets?)\\b'],
  ['ai_address',
    '\\b(?:note|message|instructions?) (?:to|for) (?:the |any |all )?(?:ai|llm|language model|model|assistant|bot' +
    '|classifier)s?\\b|\\b(?:ai|llm)(?: (?:assistant|system|model|agent|classifier)s?)? ?:|\\bassistant ?:'],
  ['routing_override',
    '\\bpre-?approved\\b|\\bno review (?:is )?needed\\b|\\b(?:skip|bypass) (?:the )?(?:human )?review\\b' +
    '|\\broute(?: this| it)?(?: ticket| request| message)? automatically\\b' +
    '|\\bclassify (?:this|it)(?: ticket| request| message)? as\\b'],
  ['field_override', '\\bpriority ?: ?(?:highest|critical|p1)\\b|\\bjira assignee\\b'],
  ['slack_mention',
    '<!(?:channel|here|everyone)\\b|<!subteam\\^|<@[uw][a-z0-9]+>|(?<![a-z0-9._%+-])@(?:here|channel|everyone)\\b'],
  ['slack_link', '<https?://[^ |>]+\\|[^>]*>'],
  ['html_comment', '<!--'],
  ['delimiter_break', '</? ?ticket ?>']
];
var INJECT_FAKE_ROLE = /^(?:\[ ?)?(?:system|assistant|developer)(?: [a-z]+)? ?[:\]]/;
var INJECT_QUOTE_MARKS = /^[ \t]*(?:>[ \t]*)+/;
var INJECT_BASE64 = /[A-Za-z0-9+/]{24,}={0,2}/g;
var BASE64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
var INJECT_QUOTE_LINE = /^[ \t]*>/;
var INJECT_ON_WROTE = /^[ \t]*On [^\n]{1,200} wrote:[ \t]*$/;
var INJECT_TICKET_TAG = /<(\/? ?ticket)/gi;
var INJECT_EDGE_SPACE = /^[ \t\r\n]+|[ \t\r\n]+$/g;
// Same class as src/common/norm.py WHITESPACE.
var INJECT_WHITESPACE = /[\t\n\x0b\x0c\r\x1c-\x20\x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+/g;

function injectLines(text) {
  return text.split('\r\n').join('\n').split('\r').join('\n').split('\n');
}

function trimSpaces(text) {
  return text.replace(/^ +| +$/g, '');
}

function scanLines(text) {
  text = text.normalize('NFKC').toLowerCase().split('_').join(' ');
  return injectLines(text).map(function (line) {
    var m = INJECT_QUOTE_MARKS.exec(line);
    return m ? line.slice(m[0].length) : line;
  });
}

function flatText(lines) {
  return trimSpaces(lines.join(' ').replace(INJECT_WHITESPACE, ' '));
}

function injectHits(text) {
  var lines = scanLines(text);
  var flat = flatText(lines);
  var found = [];
  INJECT_PHRASES.forEach(function (p) { if (new RegExp(p[1]).test(flat)) found.push(p[0]); });
  if (lines.some(function (line) { return INJECT_FAKE_ROLE.test(trimSpaces(line.replace(INJECT_WHITESPACE, ' '))); })) {
    found.push('fake_role');
  }
  return found;
}

function b64Text(token) {
  var data = token.replace(/=+$/, '');
  if (data.length % 4 === 1) return null;
  var bits = 0;
  var nbits = 0;
  var out = [];
  for (var i = 0; i < data.length; i++) {
    bits = (bits << 6) | BASE64_ALPHABET.indexOf(data[i]);
    nbits += 6;
    if (nbits >= 8) {
      nbits -= 8;
      out.push((bits >> nbits) & 0xFF);
      bits &= (1 << nbits) - 1;
    }
  }
  if (!out.length) return null;
  for (var k = 0; k < out.length; k++) {
    var b = out[k];
    if (!((b >= 32 && b <= 126) || b === 9 || b === 10 || b === 13)) return null;
  }
  return out.map(function (c) { return String.fromCharCode(c); }).join('');
}

function injectScan(subject, body, attachmentNames) {
  var parts = [subject || '', body || ''];
  (attachmentNames || []).forEach(function (n) { if (n) parts.push(String(n)); });
  var text = parts.join('\n');
  var found = {};
  injectHits(text).forEach(function (s) { found[s] = true; });
  (text.match(INJECT_BASE64) || []).forEach(function (token) {
    var decoded = b64Text(token);
    if (decoded !== null && injectHits(decoded).length) found.encoded_instruction = true;
  });
  return Object.keys(found).sort();
}

function stripQuotes(body) {
  var keep = injectLines(body || '').filter(function (line) {
    return !INJECT_QUOTE_LINE.test(line) && !INJECT_ON_WROTE.test(line);
  });
  return keep.join('\n').replace(INJECT_EDGE_SPACE, '');
}

function buildModelText(subject, body, maxModelChars) {
  if (maxModelChars === undefined || maxModelChars === null) maxModelChars = MAX_MODEL_CHARS;
  // Cap by code points, as Python len() does.
  var chars = Array.from(stripQuotes(body).replace(INJECT_TICKET_TAG, '($1'));
  var truncated = chars.length > maxModelChars ? 1 : 0;
  var capped = chars.slice(0, maxModelChars).join('');
  var subj = (subject || '').replace(INJECT_TICKET_TAG, '($1');
  return { text: 'Subject: ' + subj + '\n\n' + capped, truncated: truncated };
}

